static const LINE_EQ VP6_DcNodeEqs[5][3] = {
    { { 122, 133 }, { 133, 51 }, { 142, -16 } },
    { { 0, 1 }, { 0, 1 }, { 0, 1 } },
    { { 78, 171 }, { 169, 71 }, { 221, -30 } },
    { { 139, 117 }, { 214, 44 }, { 246, -3 } },
    { { 168, 79 }, { 210, 38 }, { 203, 17 } },
};

void VP6_ConfigureContexts(PB_INSTANCE *pbi) {
    UINT32 i;
    UINT32 Node;
    UINT32 Plane;
    INT32 Temp;

    for (Plane = 0; Plane < 2; Plane++) {
        for (i = 0; i < 3; i++) {
            for (Node = 0; Node < 5; Node++) {
                Temp = ((pbi->DcProbs[Plane * 11 + Node] * VP6_DcNodeEqs[Node][i].M + 128) >> 8) +
                       VP6_DcNodeEqs[Node][i].C;
                if (Temp > 255)
                    Temp = 255;
                Temp = Temp < 1 ? 1 : Temp;
                pbi->DcNodeContexts[Plane][i][Node] = (UINT8)Temp;
            }
        }
    }
}
